<template>
    <div class="container" id="vis">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12">
                <AboutInfo />
                <div class="block" style="min-height: 0px!important; text-align: center; padding: 0px!important;">
                    <a style="width: 100%; padding: 14px;" class="btn" @click="openPage('/')">Back</a>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import AboutInfo from "./AboutInfo";
import jQuery from "jquery";
const $ = jQuery;
window.$ = $;

export default {
  name: "AbOut",
  components: {
    AboutInfo
  },

  mounted() {
    if (innerWidth > 800 && location.pathname.toLowerCase().includes("about")) {
        location.href = '/';
    }
    $(window).resize(function () {
        if (innerWidth > 800 && location.pathname.toLowerCase().includes("about")) {
            location.href = '/';
        }});
  },
  methods: {
    openPage(name) {
        this.$router.push(name);
    },
  }
};
</script>