<template>
    <div class="block">
        <div class="slider_header"><h1>Accounting</h1>
            <hr>
            <div class="subname"><i>Manage your finances more efficiently</i></div>
        </div>
        <div class="w3-content w3-display-container" style="max-width:800px">
            <img class="mySlides w3-center fadeas" src="https://i.ibb.co/f4hthLB/1image-Try-Pagefilter.png" style="width:100%; height:calc(100% / 3)" />
            <img class="mySlides w3-center fadeas" src="https://i.ibb.co/CzM157f/1image-Try-Pagemobile.png" style="width:100%; height:calc(100% / 3)" />
            <img class="mySlides w3-center fadeas" src="https://i.ibb.co/GR8Ns1Y/1image-Try-Pagereport.png" style="width:100%; height:calc(100% / 3)" />
                <div class="w3-center w3-container w3-section w3-large w3-text-white w3-display-bottommiddle" style="width:100%; top: 0">
                    <div style="width:45%; text-align:left" class="w3-left w3-hover-text-white" @click="plusDivs(-1)"></div>
                    <div style="width:45%; text-align:right" class="w3-right w3-hover-text-white" @click="plusDivs(1)"></div>
                    <span class="w3-badge demo w3-border w3-transparent w3-hover-white" @click="currentDiv(1)"></span>
                    <span class="w3-badge demo w3-border w3-transparent w3-hover-white" @click="currentDiv(2)"></span>
                    <span class="w3-badge demo w3-border w3-transparent w3-hover-white" @click="currentDiv(3)"></span>
                </div>
        </div>
        <div style="line-height:30px; font-size: larger; font-weight:bold; text-align: center; margin: auto; padding-top: 30px; width:80%">
            Want to start managing your finances effortlessly and more efficiently?
            Forget spreadsheets and complex algorithms, this is the tool you need!
        </div>
        <p style="padding-top:30px; padding-bottom: 10px; font-size:medium!important; width:95%; text-align: center; margin: auto">
            Our main goal is to help you figuring out for what reason you spend or earn money.<br />
            With this tool you can manage your finances anywhere anytime,<br />
            without the need to collect all the receipts.
        </p>
    </div>
</template>

<script>
export default {
  name: "AboutInfo",
  data() {
    return {
        slideIndex: 1
    }
  },

  mounted() {
    this.showDivs(this.slideIndex);

    setInterval(this.plusDivs, 30000, 1);
  },

  methods: {
      plusDivs(n) {
        this.showDivs(this.slideIndex += n);
    },

    currentDiv(n) {
        this.showDivs(this.slideIndex = n);
    },

    showDivs(n) {
        let i;
        let x = document.getElementsByClassName("mySlides");
        let dots = document.getElementsByClassName("demo");

        if(x && x.length > 0 && dots && dots.length > 0) {
            if (n > x.length) { this.slideIndex = 1 }
            if (n < 1) { this.slideIndex = x.length }
            for (i = 0; i < x.length; i++) {
                x[i].style.display = "none";
            }
            for (i = 0; i < dots.length; i++) {
                dots[i].className = dots[i].className.replace(" w3-white", "");
            }
            x[this.slideIndex - 1].style.display = "block";
            dots[this.slideIndex - 1].className += " w3-white";
        }
    }
  }
};
</script>